using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalTests
{
    private readonly CalculatePayableTotal _useCase = new(new LoyaltyDiscountPolicy());

    [Fact]
    public void Gold_member_gets_five_percent_off_a_10000_cent_subtotal()
    {
        var actualPayableTotalCents = _useCase.For(10_000, LoyaltyTier.Gold);

        Assert.Equal(9_500, actualPayableTotalCents);
    }

    [Fact]
    public void Gold_member_gets_five_percent_off_a_20000_cent_subtotal()
    {
        var actualPayableTotalCents = _useCase.For(20_000, LoyaltyTier.Gold);

        Assert.Equal(19_000, actualPayableTotalCents);
    }

    [Fact]
    public void Gold_member_gets_five_percent_off_a_5000_cent_subtotal()
    {
        var actualPayableTotalCents = _useCase.For(5_000, LoyaltyTier.Gold);

        Assert.Equal(4_750, actualPayableTotalCents);
    }

    [Fact]
    public void Gold_member_pays_nothing_on_an_empty_basket()
    {
        var actualPayableTotalCents = _useCase.For(0, LoyaltyTier.Gold);

        Assert.Equal(0, actualPayableTotalCents);
    }
}
EOF
